# ! [doc = " Windows-specific extensions to primitives in the [`std::fs`] module."] # ! [doc = ""] # ! [doc = " [`std::fs`]: crate::fs"] # ! [stable (feature = "rust1" , since = "1.0.0")] use split_decls_genesis :: ourprelude :: * ; use crate :: fs :: { self , Metadata , OpenOptions } ; use crate :: io :: BorrowedCursor ; use crate :: path :: Path ; use crate :: sealed :: Sealed ; use crate :: sys_common :: { AsInner , AsInnerMut , IntoInner } ; use crate :: time :: SystemTime ; use crate :: { io , sys } ; #[doc = " Windows-specific extensions to [`fs::File`]."] #[stable (feature = "file_offset" , since = "1.15.0")] pub trait FileExt { #[doc = " Seeks to a given position and reads a number of bytes."] #[doc = ""] #[doc = " Returns the number of bytes read."] #[doc = ""] #[doc = " The offset is relative to the start of the file and thus independent"] #[doc = " from the current cursor. The current cursor **is** affected by this"] #[doc = " function, it is set to the end of the read."] #[doc = ""] #[doc = " Reading beyond the end of the file will always return with a length of"] #[doc = " 0\\."] #[doc = ""] #[doc = " Note that similar to `File::read`, it is not an error to return with a"] #[doc = " short read. When returning from such a short read, the file pointer is"] #[doc = " still updated."] #[doc = ""] #[doc = " # Examples"] #[doc = ""] #[doc = " ```no_run"] #[doc = " use std::io;"] #[doc = " use std::fs::File;"] #[doc = " use std::os::windows::prelude::*;"] #[doc = ""] #[doc = " fn main() -> io::Result<()> {"] #[doc = "     let mut file = File::open(\"foo.txt\")?;"] #[doc = "     let mut buffer = [0; 10];"] #[doc = ""] #[doc = "     // Read 10 bytes, starting 72 bytes from the"] #[doc = "     // start of the file."] #[doc = "     file.seek_read(&mut buffer[..], 72)?;"] #[doc = "     Ok(())"] #[doc = " }"] #[doc = " ```"] #[stable (feature = "file_offset" , since = "1.15.0")] fn seek_read (& self , buf : & mut [u8] , offset : u64) -> io :: Result < usize > ; #[doc = " Seeks to a given position and reads some bytes into the buffer."] #[doc = ""] #[doc = " This is equivalent to the [`seek_read`](FileExt::seek_read) method, except that it is passed"] #[doc = " a [`BorrowedCursor`] rather than `&mut [u8]` to allow use with uninitialized buffers. The"] #[doc = " new data will be appended to any existing contents of `buf`."] #[doc = ""] #[doc = " Reading beyond the end of the file will always succeed without reading any bytes."] #[doc = ""] #[doc = " # Examples"] #[doc = ""] #[doc = " ```no_run"] #[doc = " #![feature(core_io_borrowed_buf)]"] #[doc = " #![feature(read_buf_at)]"] #[doc = ""] #[doc = " use std::io;"] #[doc = " use std::io::BorrowedBuf;"] #[doc = " use std::fs::File;"] #[doc = " use std::mem::MaybeUninit;"] #[doc = " use std::os::windows::prelude::*;"] #[doc = ""] #[doc = " fn main() -> io::Result<()> {"] #[doc = "     let mut file = File::open(\"pi.txt\")?;"] #[doc = ""] #[doc = "     // Read some bytes starting from offset 2"] #[doc = "     let mut buf: [MaybeUninit<u8>; 10] = [MaybeUninit::uninit(); 10];"] #[doc = "     let mut buf = BorrowedBuf::from(buf.as_mut_slice());"] #[doc = "     file.seek_read_buf(buf.unfilled(), 2)?;"] #[doc = ""] #[doc = "     assert!(buf.filled().starts_with(b\"1\"));"] #[doc = ""] #[doc = "     Ok(())"] #[doc = " }"] #[doc = " ```"] #[unstable (feature = "read_buf_at" , issue = "140771")] fn seek_read_buf (& self , buf : BorrowedCursor < '_ > , offset : u64) -> io :: Result < () > { io :: default_read_buf (| b | self . seek_read (b , offset) , buf) } #[doc = " Seeks to a given position and writes a number of bytes."] #[doc = ""] #[doc = " Returns the number of bytes written."] #[doc = ""] #[doc = " The offset is relative to the start of the file and thus independent"] #[doc = " from the current cursor. The current cursor **is** affected by this"] #[doc = " function, it is set to the end of the write."] #[doc = ""] #[doc = " When writing beyond the end of the file, the file is appropriately"] #[doc = " extended and the intermediate bytes are set to zero."] #[doc = ""] #[doc = " Note that similar to `File::write`, it is not an error to return a"] #[doc = " short write. When returning from such a short write, the file pointer"] #[doc = " is still updated."] #[doc = ""] #[doc = " # Examples"] #[doc = ""] #[doc = " ```no_run"] #[doc = " use std::fs::File;"] #[doc = " use std::os::windows::prelude::*;"] #[doc = ""] #[doc = " fn main() -> std::io::Result<()> {"] #[doc = "     let mut buffer = File::create(\"foo.txt\")?;"] #[doc = ""] #[doc = "     // Write a byte string starting 72 bytes from"] #[doc = "     // the start of the file."] #[doc = "     buffer.seek_write(b\"some bytes\", 72)?;"] #[doc = "     Ok(())"] #[doc = " }"] #[doc = " ```"] #[stable (feature = "file_offset" , since = "1.15.0")] fn seek_write (& self , buf : & [u8] , offset : u64) -> io :: Result < usize > ; } #[stable (feature = "file_offset" , since = "1.15.0")] impl FileExt for fs :: File { fn seek_read (& self , buf : & mut [u8] , offset : u64) -> io :: Result < usize > { self . as_inner () . read_at (buf , offset) } fn seek_read_buf (& self , buf : BorrowedCursor < '_ > , offset : u64) -> io :: Result < () > { self . as_inner () . read_buf_at (buf , offset) } fn seek_write (& self , buf : & [u8] , offset : u64) -> io :: Result < usize > { self . as_inner () . write_at (buf , offset) } } #[doc = " Windows-specific extensions to [`fs::OpenOptions`]."] #[stable (feature = "open_options_ext" , since = "1.10.0")] pub trait OpenOptionsExt { #[doc = " Overrides the `dwDesiredAccess` argument to the call to [`CreateFile`]"] #[doc = " with the specified value."] #[doc = ""] #[doc = " This will override the `read`, `write`, and `append` flags on the"] #[doc = " `OpenOptions` structure. This method provides fine-grained control over"] #[doc = " the permissions to read, write and append data, attributes (like hidden"] #[doc = " and system), and extended attributes."] #[doc = ""] #[doc = " # Examples"] #[doc = ""] #[doc = " ```no_run"] #[doc = " use std::fs::OpenOptions;"] #[doc = " use std::os::windows::prelude::*;"] #[doc = ""] #[doc = " // Open without read and write permission, for example if you only need"] #[doc = " // to call `stat` on the file"] #[doc = " let file = OpenOptions::new().access_mode(0).open(\"foo.txt\");"] #[doc = " ```"] #[doc = ""] #[doc = " [`CreateFile`]: https://docs.microsoft.com/en-us/windows/win32/api/fileapi/nf-fileapi-createfilea"] #[stable (feature = "open_options_ext" , since = "1.10.0")] fn access_mode (& mut self , access : u32) -> & mut Self ; #[doc = " Overrides the `dwShareMode` argument to the call to [`CreateFile`] with"] #[doc = " the specified value."] #[doc = ""] #[doc = " By default `share_mode` is set to"] #[doc = " `FILE_SHARE_READ | FILE_SHARE_WRITE | FILE_SHARE_DELETE`. This allows"] #[doc = " other processes to read, write, and delete/rename the same file"] #[doc = " while it is open. Removing any of the flags will prevent other"] #[doc = " processes from performing the corresponding operation until the file"] #[doc = " handle is closed."] #[doc = ""] #[doc = " # Examples"] #[doc = ""] #[doc = " ```no_run"] #[doc = " use std::fs::OpenOptions;"] #[doc = " use std::os::windows::prelude::*;"] #[doc = ""] #[doc = " // Do not allow others to read or modify this file while we have it open"] #[doc = " // for writing."] #[doc = " let file = OpenOptions::new()"] #[doc = "     .write(true)"] #[doc = "     .share_mode(0)"] #[doc = "     .open(\"foo.txt\");"] #[doc = " ```"] #[doc = ""] #[doc = " [`CreateFile`]: https://docs.microsoft.com/en-us/windows/win32/api/fileapi/nf-fileapi-createfilea"] #[stable (feature = "open_options_ext" , since = "1.10.0")] fn share_mode (& mut self , val : u32) -> & mut Self ; #[doc = " Sets extra flags for the `dwFileFlags` argument to the call to"] #[doc = " [`CreateFile2`] to the specified value (or combines it with"] #[doc = " `attributes` and `security_qos_flags` to set the `dwFlagsAndAttributes`"] #[doc = " for [`CreateFile`])."] #[doc = ""] #[doc = " Custom flags can only set flags, not remove flags set by Rust's options."] #[doc = " This option overwrites any previously set custom flags."] #[doc = ""] #[doc = " # Examples"] #[doc = ""] #[doc = " ```no_run"] #[doc = " # #![allow(unexpected_cfgs)]"] #[doc = " # #[cfg(for_demonstration_only)]"] #[doc = " extern crate winapi;"] #[doc = " # mod winapi { pub const FILE_FLAG_DELETE_ON_CLOSE: u32 = 0x04000000; }"] #[doc = ""] #[doc = " use std::fs::OpenOptions;"] #[doc = " use std::os::windows::prelude::*;"] #[doc = ""] #[doc = " let file = OpenOptions::new()"] #[doc = "     .create(true)"] #[doc = "     .write(true)"] #[doc = "     .custom_flags(winapi::FILE_FLAG_DELETE_ON_CLOSE)"] #[doc = "     .open(\"foo.txt\");"] #[doc = " ```"] #[doc = ""] #[doc = " [`CreateFile`]: https://docs.microsoft.com/en-us/windows/win32/api/fileapi/nf-fileapi-createfilea"] #[doc = " [`CreateFile2`]: https://docs.microsoft.com/en-us/windows/win32/api/fileapi/nf-fileapi-createfile2"] #[stable (feature = "open_options_ext" , since = "1.10.0")] fn custom_flags (& mut self , flags : u32) -> & mut Self ; #[doc = " Sets the `dwFileAttributes` argument to the call to [`CreateFile2`] to"] #[doc = " the specified value (or combines it with `custom_flags` and"] #[doc = " `security_qos_flags` to set the `dwFlagsAndAttributes` for"] #[doc = " [`CreateFile`])."] #[doc = ""] #[doc = " If a _new_ file is created because it does not yet exist and"] #[doc = " `.create(true)` or `.create_new(true)` are specified, the new file is"] #[doc = " given the attributes declared with `.attributes()`."] #[doc = ""] #[doc = " If an _existing_ file is opened with `.create(true).truncate(true)`, its"] #[doc = " existing attributes are preserved and combined with the ones declared"] #[doc = " with `.attributes()`."] #[doc = ""] #[doc = " In all other cases the attributes get ignored."] #[doc = ""] #[doc = " # Examples"] #[doc = ""] #[doc = " ```no_run"] #[doc = " # #![allow(unexpected_cfgs)]"] #[doc = " # #[cfg(for_demonstration_only)]"] #[doc = " extern crate winapi;"] #[doc = " # mod winapi { pub const FILE_ATTRIBUTE_HIDDEN: u32 = 2; }"] #[doc = ""] #[doc = " use std::fs::OpenOptions;"] #[doc = " use std::os::windows::prelude::*;"] #[doc = ""] #[doc = " let file = OpenOptions::new()"] #[doc = "     .write(true)"] #[doc = "     .create(true)"] #[doc = "     .attributes(winapi::FILE_ATTRIBUTE_HIDDEN)"] #[doc = "     .open(\"foo.txt\");"] #[doc = " ```"] #[doc = ""] #[doc = " [`CreateFile`]: https://docs.microsoft.com/en-us/windows/win32/api/fileapi/nf-fileapi-createfilea"] #[doc = " [`CreateFile2`]: https://docs.microsoft.com/en-us/windows/win32/api/fileapi/nf-fileapi-createfile2"] #[stable (feature = "open_options_ext" , since = "1.10.0")] fn attributes (& mut self , val : u32) -> & mut Self ; #[doc = " Sets the `dwSecurityQosFlags` argument to the call to [`CreateFile2`] to"] #[doc = " the specified value (or combines it with `custom_flags` and `attributes`"] #[doc = " to set the `dwFlagsAndAttributes` for [`CreateFile`])."] #[doc = ""] #[doc = " By default `security_qos_flags` is not set. It should be specified when"] #[doc = " opening a named pipe, to control to which degree a server process can"] #[doc = " act on behalf of a client process (security impersonation level)."] #[doc = ""] #[doc = " When `security_qos_flags` is not set, a malicious program can gain the"] #[doc = " elevated privileges of a privileged Rust process when it allows opening"] #[doc = " user-specified paths, by tricking it into opening a named pipe. So"] #[doc = " arguably `security_qos_flags` should also be set when opening arbitrary"] #[doc = " paths. However the bits can then conflict with other flags, specifically"] #[doc = " `FILE_FLAG_OPEN_NO_RECALL`."] #[doc = ""] #[doc = " For information about possible values, see [Impersonation Levels] on the"] #[doc = " Windows Dev Center site. The `SECURITY_SQOS_PRESENT` flag is set"] #[doc = " automatically when using this method."] #[doc = " # Examples"] #[doc = ""] #[doc = " ```no_run"] #[doc = " # #![allow(unexpected_cfgs)]"] #[doc = " # #[cfg(for_demonstration_only)]"] #[doc = " extern crate winapi;"] #[doc = " # mod winapi { pub const SECURITY_IDENTIFICATION: u32 = 0; }"] #[doc = " use std::fs::OpenOptions;"] #[doc = " use std::os::windows::prelude::*;"] #[doc = ""] #[doc = " let file = OpenOptions::new()"] #[doc = "     .write(true)"] #[doc = "     .create(true)"] #[doc = ""] #[doc = "     // Sets the flag value to `SecurityIdentification`."] #[doc = "     .security_qos_flags(winapi::SECURITY_IDENTIFICATION)"] #[doc = ""] #[doc = "     .open(r\"\\\\.\\pipe\\MyPipe\");"] #[doc = " ```"] #[doc = ""] #[doc = " [`CreateFile`]: https://docs.microsoft.com/en-us/windows/win32/api/fileapi/nf-fileapi-createfilea"] #[doc = " [`CreateFile2`]: https://docs.microsoft.com/en-us/windows/win32/api/fileapi/nf-fileapi-createfile2"] #[doc = " [Impersonation Levels]:"] #[doc = "     https://docs.microsoft.com/en-us/windows/win32/api/winnt/ne-winnt-security_impersonation_level"] #[stable (feature = "open_options_ext" , since = "1.10.0")] fn security_qos_flags (& mut self , flags : u32) -> & mut Self ; } #[stable (feature = "open_options_ext" , since = "1.10.0")] impl OpenOptionsExt for OpenOptions { fn access_mode (& mut self , access : u32) -> & mut OpenOptions { self . as_inner_mut () . access_mode (access) ; self } fn share_mode (& mut self , share : u32) -> & mut OpenOptions { self . as_inner_mut () . share_mode (share) ; self } fn custom_flags (& mut self , flags : u32) -> & mut OpenOptions { self . as_inner_mut () . custom_flags (flags) ; self } fn attributes (& mut self , attributes : u32) -> & mut OpenOptions { self . as_inner_mut () . attributes (attributes) ; self } fn security_qos_flags (& mut self , flags : u32) -> & mut OpenOptions { self . as_inner_mut () . security_qos_flags (flags) ; self } } #[doc = " Windows-specific extensions to [`fs::Metadata`]."] #[doc = ""] #[doc = " The data members that this trait exposes correspond to the members"] #[doc = " of the [`BY_HANDLE_FILE_INFORMATION`] structure."] #[doc = ""] #[doc = " [`BY_HANDLE_FILE_INFORMATION`]:"] #[doc = "     https://docs.microsoft.com/windows/win32/api/fileapi/ns-fileapi-by_handle_file_information"] #[stable (feature = "metadata_ext" , since = "1.1.0")] pub trait MetadataExt { #[doc = " Returns the value of the `dwFileAttributes` field of this metadata."] #[doc = ""] #[doc = " This field contains the file system attribute information for a file"] #[doc = " or directory. For possible values and their descriptions, see"] #[doc = " [File Attribute Constants] in the Windows Dev Center."] #[doc = ""] #[doc = " # Examples"] #[doc = ""] #[doc = " ```no_run"] #[doc = " use std::io;"] #[doc = " use std::fs;"] #[doc = " use std::os::windows::prelude::*;"] #[doc = ""] #[doc = " fn main() -> io::Result<()> {"] #[doc = "     let metadata = fs::metadata(\"foo.txt\")?;"] #[doc = "     let attributes = metadata.file_attributes();"] #[doc = "     Ok(())"] #[doc = " }"] #[doc = " ```"] #[doc = ""] #[doc = " [File Attribute Constants]:"] #[doc = "     https://docs.microsoft.com/windows/win32/fileio/file-attribute-constants"] #[stable (feature = "metadata_ext" , since = "1.1.0")] fn file_attributes (& self) -> u32 ; #[doc = " Returns the value of the `ftCreationTime` field of this metadata."] #[doc = ""] #[doc = " The returned 64-bit value is equivalent to a [`FILETIME`] struct,"] #[doc = " which represents the number of 100-nanosecond intervals since"] #[doc = " January 1, 1601 (UTC). The struct is automatically"] #[doc = " converted to a `u64` value, as that is the recommended way"] #[doc = " to use it."] #[doc = ""] #[doc = " If the underlying filesystem does not support creation time, the"] #[doc = " returned value is 0."] #[doc = ""] #[doc = " # Examples"] #[doc = ""] #[doc = " ```no_run"] #[doc = " use std::io;"] #[doc = " use std::fs;"] #[doc = " use std::os::windows::prelude::*;"] #[doc = ""] #[doc = " fn main() -> io::Result<()> {"] #[doc = "     let metadata = fs::metadata(\"foo.txt\")?;"] #[doc = "     let creation_time = metadata.creation_time();"] #[doc = "     Ok(())"] #[doc = " }"] #[doc = " ```"] #[doc = ""] #[doc = " [`FILETIME`]: https://docs.microsoft.com/windows/win32/api/minwinbase/ns-minwinbase-filetime"] #[stable (feature = "metadata_ext" , since = "1.1.0")] fn creation_time (& self) -> u64 ; #[doc = " Returns the value of the `ftLastAccessTime` field of this metadata."] #[doc = ""] #[doc = " The returned 64-bit value is equivalent to a [`FILETIME`] struct,"] #[doc = " which represents the number of 100-nanosecond intervals since"] #[doc = " January 1, 1601 (UTC). The struct is automatically"] #[doc = " converted to a `u64` value, as that is the recommended way"] #[doc = " to use it."] #[doc = ""] #[doc = " For a file, the value specifies the last time that a file was read"] #[doc = " from or written to. For a directory, the value specifies when"] #[doc = " the directory was created. For both files and directories, the"] #[doc = " specified date is correct, but the time of day is always set to"] #[doc = " midnight."] #[doc = ""] #[doc = " If the underlying filesystem does not support last access time, the"] #[doc = " returned value is 0."] #[doc = ""] #[doc = " # Examples"] #[doc = ""] #[doc = " ```no_run"] #[doc = " use std::io;"] #[doc = " use std::fs;"] #[doc = " use std::os::windows::prelude::*;"] #[doc = ""] #[doc = " fn main() -> io::Result<()> {"] #[doc = "     let metadata = fs::metadata(\"foo.txt\")?;"] #[doc = "     let last_access_time = metadata.last_access_time();"] #[doc = "     Ok(())"] #[doc = " }"] #[doc = " ```"] #[doc = ""] #[doc = " [`FILETIME`]: https://docs.microsoft.com/windows/win32/api/minwinbase/ns-minwinbase-filetime"] #[stable (feature = "metadata_ext" , since = "1.1.0")] fn last_access_time (& self) -> u64 ; #[doc = " Returns the value of the `ftLastWriteTime` field of this metadata."] #[doc = ""] #[doc = " The returned 64-bit value is equivalent to a [`FILETIME`] struct,"] #[doc = " which represents the number of 100-nanosecond intervals since"] #[doc = " January 1, 1601 (UTC). The struct is automatically"] #[doc = " converted to a `u64` value, as that is the recommended way"] #[doc = " to use it."] #[doc = ""] #[doc = " For a file, the value specifies the last time that a file was written"] #[doc = " to. For a directory, the structure specifies when the directory was"] #[doc = " created."] #[doc = ""] #[doc = " If the underlying filesystem does not support the last write time,"] #[doc = " the returned value is 0."] #[doc = ""] #[doc = " # Examples"] #[doc = ""] #[doc = " ```no_run"] #[doc = " use std::io;"] #[doc = " use std::fs;"] #[doc = " use std::os::windows::prelude::*;"] #[doc = ""] #[doc = " fn main() -> io::Result<()> {"] #[doc = "     let metadata = fs::metadata(\"foo.txt\")?;"] #[doc = "     let last_write_time = metadata.last_write_time();"] #[doc = "     Ok(())"] #[doc = " }"] #[doc = " ```"] #[doc = ""] #[doc = " [`FILETIME`]: https://docs.microsoft.com/windows/win32/api/minwinbase/ns-minwinbase-filetime"] #[stable (feature = "metadata_ext" , since = "1.1.0")] fn last_write_time (& self) -> u64 ; #[doc = " Returns the value of the `nFileSize` fields of this"] #[doc = " metadata."] #[doc = ""] #[doc = " The returned value does not have meaning for directories."] #[doc = ""] #[doc = " # Examples"] #[doc = ""] #[doc = " ```no_run"] #[doc = " use std::io;"] #[doc = " use std::fs;"] #[doc = " use std::os::windows::prelude::*;"] #[doc = ""] #[doc = " fn main() -> io::Result<()> {"] #[doc = "     let metadata = fs::metadata(\"foo.txt\")?;"] #[doc = "     let file_size = metadata.file_size();"] #[doc = "     Ok(())"] #[doc = " }"] #[doc = " ```"] #[stable (feature = "metadata_ext" , since = "1.1.0")] fn file_size (& self) -> u64 ; #[doc = " Returns the value of the `dwVolumeSerialNumber` field of this"] #[doc = " metadata."] #[doc = ""] #[doc = " This will return `None` if the `Metadata` instance was created from a"] #[doc = " call to `DirEntry::metadata`. If this `Metadata` was created by using"] #[doc = " `fs::metadata` or `File::metadata`, then this will return `Some`."] #[unstable (feature = "windows_by_handle" , issue = "63010")] fn volume_serial_number (& self) -> Option < u32 > ; #[doc = " Returns the value of the `nNumberOfLinks` field of this"] #[doc = " metadata."] #[doc = ""] #[doc = " This will return `None` if the `Metadata` instance was created from a"] #[doc = " call to `DirEntry::metadata`. If this `Metadata` was created by using"] #[doc = " `fs::metadata` or `File::metadata`, then this will return `Some`."] #[unstable (feature = "windows_by_handle" , issue = "63010")] fn number_of_links (& self) -> Option < u32 > ; #[doc = " Returns the value of the `nFileIndex` fields of this"] #[doc = " metadata."] #[doc = ""] #[doc = " This will return `None` if the `Metadata` instance was created from a"] #[doc = " call to `DirEntry::metadata`. If this `Metadata` was created by using"] #[doc = " `fs::metadata` or `File::metadata`, then this will return `Some`."] #[unstable (feature = "windows_by_handle" , issue = "63010")] fn file_index (& self) -> Option < u64 > ; #[doc = " Returns the value of the `ChangeTime` fields of this metadata."] #[doc = ""] #[doc = " `ChangeTime` is the last time file metadata was changed, such as"] #[doc = " renames, attributes, etc."] #[doc = ""] #[doc = " This will return `None` if `Metadata` instance was created from a call to"] #[doc = " `DirEntry::metadata` or if the `target_vendor` is outside the current platform"] #[doc = " support for this api."] #[unstable (feature = "windows_change_time" , issue = "121478")] fn change_time (& self) -> Option < u64 > ; } #[stable (feature = "metadata_ext" , since = "1.1.0")] impl MetadataExt for Metadata { fn file_attributes (& self) -> u32 { self . as_inner () . attrs () } fn creation_time (& self) -> u64 { self . as_inner () . created_u64 () } fn last_access_time (& self) -> u64 { self . as_inner () . accessed_u64 () } fn last_write_time (& self) -> u64 { self . as_inner () . modified_u64 () } fn file_size (& self) -> u64 { self . as_inner () . size () } fn volume_serial_number (& self) -> Option < u32 > { self . as_inner () . volume_serial_number () } fn number_of_links (& self) -> Option < u32 > { self . as_inner () . number_of_links () } fn file_index (& self) -> Option < u64 > { self . as_inner () . file_index () } fn change_time (& self) -> Option < u64 > { self . as_inner () . changed_u64 () } } #[doc = " Windows-specific extensions to [`fs::FileType`]."] #[doc = ""] #[doc = " On Windows, a symbolic link knows whether it is a file or directory."] #[stable (feature = "windows_file_type_ext" , since = "1.64.0")] pub trait FileTypeExt : Sealed { #[doc = " Returns `true` if this file type is a symbolic link that is also a directory."] #[stable (feature = "windows_file_type_ext" , since = "1.64.0")] fn is_symlink_dir (& self) -> bool ; #[doc = " Returns `true` if this file type is a symbolic link that is also a file."] #[stable (feature = "windows_file_type_ext" , since = "1.64.0")] fn is_symlink_file (& self) -> bool ; } #[stable (feature = "windows_file_type_ext" , since = "1.64.0")] impl Sealed for fs :: FileType { } #[stable (feature = "windows_file_type_ext" , since = "1.64.0")] impl FileTypeExt for fs :: FileType { fn is_symlink_dir (& self) -> bool { self . as_inner () . is_symlink_dir () } fn is_symlink_file (& self) -> bool { self . as_inner () . is_symlink_file () } } #[doc = " Windows-specific extensions to [`fs::FileTimes`]."] #[stable (feature = "file_set_times" , since = "1.75.0")] pub trait FileTimesExt : Sealed { #[doc = " Set the creation time of a file."] #[stable (feature = "file_set_times" , since = "1.75.0")] fn set_created (self , t : SystemTime) -> Self ; } #[stable (feature = "file_set_times" , since = "1.75.0")] impl FileTimesExt for fs :: FileTimes { fn set_created (mut self , t : SystemTime) -> Self { self . as_inner_mut () . set_created (t . into_inner ()) ; self } } #[doc = " Creates a new symlink to a non-directory file on the filesystem."] #[doc = ""] #[doc = " The `link` path will be a file symbolic link pointing to the `original`"] #[doc = " path."] #[doc = ""] #[doc = " The `original` path should not be a directory or a symlink to a directory,"] #[doc = " otherwise the symlink will be broken. Use [`symlink_dir`] for directories."] #[doc = ""] #[doc = " This function currently corresponds to [`CreateSymbolicLinkW`][CreateSymbolicLinkW]."] #[doc = " Note that this [may change in the future][changes]."] #[doc = ""] #[doc = " [CreateSymbolicLinkW]: https://docs.microsoft.com/en-us/windows/win32/api/winbase/nf-winbase-createsymboliclinkw"] #[doc = " [changes]: io#platform-specific-behavior"] #[doc = ""] #[doc = " # Examples"] #[doc = ""] #[doc = " ```no_run"] #[doc = " use std::os::windows::fs;"] #[doc = ""] #[doc = " fn main() -> std::io::Result<()> {"] #[doc = "     fs::symlink_file(\"a.txt\", \"b.txt\")?;"] #[doc = "     Ok(())"] #[doc = " }"] #[doc = " ```"] #[doc = ""] #[doc = " # Limitations"] #[doc = ""] #[doc = " Windows treats symlink creation as a [privileged action][symlink-security],"] #[doc = " therefore this function is likely to fail unless the user makes changes to"] #[doc = " their system to permit symlink creation. Users can try enabling Developer"] #[doc = " Mode, granting the `SeCreateSymbolicLinkPrivilege` privilege, or running"] #[doc = " the process as an administrator."] #[doc = ""] #[doc = " [symlink-security]: https://docs.microsoft.com/en-us/windows/security/threat-protection/security-policy-settings/create-symbolic-links"] #[stable (feature = "symlink" , since = "1.1.0")] pub fn symlink_file < P : AsRef < Path > , Q : AsRef < Path > > (original : P , link : Q) -> io :: Result < () > { sys :: fs :: symlink_inner (original . as_ref () , link . as_ref () , false) } #[doc = " Creates a new symlink to a directory on the filesystem."] #[doc = ""] #[doc = " The `link` path will be a directory symbolic link pointing to the `original`"] #[doc = " path."] #[doc = ""] #[doc = " The `original` path must be a directory or a symlink to a directory,"] #[doc = " otherwise the symlink will be broken. Use [`symlink_file`] for other files."] #[doc = ""] #[doc = " This function currently corresponds to [`CreateSymbolicLinkW`][CreateSymbolicLinkW]."] #[doc = " Note that this [may change in the future][changes]."] #[doc = ""] #[doc = " [CreateSymbolicLinkW]: https://docs.microsoft.com/en-us/windows/win32/api/winbase/nf-winbase-createsymboliclinkw"] #[doc = " [changes]: io#platform-specific-behavior"] #[doc = ""] #[doc = " # Examples"] #[doc = ""] #[doc = " ```no_run"] #[doc = " use std::os::windows::fs;"] #[doc = ""] #[doc = " fn main() -> std::io::Result<()> {"] #[doc = "     fs::symlink_dir(\"a\", \"b\")?;"] #[doc = "     Ok(())"] #[doc = " }"] #[doc = " ```"] #[doc = ""] #[doc = " # Limitations"] #[doc = ""] #[doc = " Windows treats symlink creation as a [privileged action][symlink-security],"] #[doc = " therefore this function is likely to fail unless the user makes changes to"] #[doc = " their system to permit symlink creation. Users can try enabling Developer"] #[doc = " Mode, granting the `SeCreateSymbolicLinkPrivilege` privilege, or running"] #[doc = " the process as an administrator."] #[doc = ""] #[doc = " [symlink-security]: https://docs.microsoft.com/en-us/windows/security/threat-protection/security-policy-settings/create-symbolic-links"] #[stable (feature = "symlink" , since = "1.1.0")] pub fn symlink_dir < P : AsRef < Path > , Q : AsRef < Path > > (original : P , link : Q) -> io :: Result < () > { sys :: fs :: symlink_inner (original . as_ref () , link . as_ref () , true) } #[doc = " Creates a junction point."] #[doc = ""] #[doc = " The `link` path will be a directory junction pointing to the original path."] #[doc = " If `link` is a relative path then it will be made absolute prior to creating the junction point."] #[doc = " The `original` path must be a directory or a link to a directory, otherwise the junction point will be broken."] #[doc = ""] #[doc = " If either path is not a local file path then this will fail."] #[unstable (feature = "junction_point" , issue = "121709")] pub fn junction_point < P : AsRef < Path > , Q : AsRef < Path > > (original : P , link : Q) -> io :: Result < () > { sys :: fs :: junction_point (original . as_ref () , link . as_ref ()) }